content:
{
    "criteria": [
        {
            "section": "一、合同主体",
            "id": "1.1",
            "criterion": "通过工商登记及司法公开平台核查签约主体是否存在未了结的重大涉法涉诉事项",
            "check_points": [
                "查询国家企业信用信息公示系统，核实企业存续状态及经营异常记录",
                "检索中国裁判文书网、执行信息公开网，确认是否存在作为被告/被执行人的重大诉讼、仲裁或失信记录",
                "重点核查标的金额超过人民币50万元的未结案件"
            ]
        },
        {
            "section": "一、合同主体",
            "id": "1.2",
            "criterion": "核对签约主体营业执照记载的经营范围，确认合同项下标的物或服务属于其法定经营范围",
            "check_points": [
                "提取营业执照副本中‘经营范围’全文",
                "逐条比对合同约定的服务内容、产品类型、技术开发/实施等事项是否落入该范围",
                "如涉及特许经营（如金融、医疗、教育、数据处理等），额外核查是否具备相应行政许可资质"
            ]
        },
        {
            "section": "一、合同主体",
            "id": "1.3",
            "criterion": "核验合同载明的签约方基本信息是否完整、准确，且与工商登记信息完全一致",
            "check_points": [
                "比对合同首部及签署页中企业全称、统一社会信用代码、法定代表人/负责人姓名",
                "核对注册地址、实际办公地址、联系电话、传真、电子邮箱等联络信息是否与最新工商登记一致",
                "确认联系人姓名、职务、电话是否明确填写，且非使用‘甲方指定人员’等模糊表述"
            ]
        },
        {
            "section": "一、合同主体",
            "id": "1.4",
            "criterion": "对于软件采购类合同，核查供方是否拥有合同项下软件的核心知识产权，或已获合法授权",
            "check_points": [
                "要求供方提供软件著作权登记证书或授权链文件（含原始权利人→被授权人→供方的完整链条）",
                "审查合同中是否明确约定知识产权归属（如交付成果著作权归采购方所有）",
                "核查是否存在开源组件使用，及是否符合GPL等传染性许可证合规要求"
            ]
        },
        {
            "section": "二、合同框架",
            "id": "2.1",
            "criterion": "合同是否完整涵盖关键条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权、质量保证、交付、验收、完成时限、违约责任、争议解决（司法管辖）、不可抗力、廉洁承诺、变更机制、份数及电子送达约定",
            "check_points": [
                "逐项勾选上述14类条款是否存在，缺失项须标注并提示补正",
                "特别聚焦‘争议解决’条款：是否明确约定仲裁机构全称或管辖法院具体名称（如‘北京仲裁委员会’或‘上海市浦东新区人民法院’），排除‘原告所在地法院’等无效约定",
                "核查争议解决方式是否与主合同性质匹配（如涉外合同可约定境外仲裁，但需符合《仲裁法》及司法解释）"
            ]
        },
        {
            "section": "二、合同框架",
            "id": "2.2",
            "criterion": "合同是否明确指定主要项目负责人，并完整载明其姓名、身份证号码及联系电话",
            "check_points": [
                "检查合同正文或附件中是否设置‘项目负责人’专条",
                "确认所列负责人信息为自然人身份，且身份证号符合18位编码规则（含X校验）",
                "核对电话号码格式是否为有效中国大陆手机号或固话（含区号）"
            ]
        },
        {
            "section": "二、合同框架",
            "id": "2.3",
            "criterion": "采购内容是否具体、可识别，包括品种、规格、型号、等级、花色等要素；必要时是否通过附件予以详尽说明",
            "check_points": [
                "检查标的描述是否避免‘详见附件’而无附件、或附件为空白/未签署",
                "确认技术参数、执行标准（如GB/T、ISO）、配置清单等是否量化、无歧义",
                "如为定制开发，是否明确需求文档编号及版本号，并约定其为合同组成部分"
            ]
        },
        {
            "section": "二、合同框架",
            "id": "2.4",
            "criterion": "合同金额是否清晰列明数量、单价、总价、币种及计量单位，且大小写一致",
            "check_points": [
                "核对数字金额与中文大写金额是否完全对应（如‘¥1,234,567.89’对应‘人民币壹佰贰拾叁万肆仟伍佰陆拾柒元捌角玖分’）",
                "确认单价×数量=总价，各分项金额合计等于合同总金额",
                "检查币种是否明确标注‘人民币’或‘USD’等，不得仅用符号‘￥’代替"
            ]
        },
        {
            "section": "二、合同框架",
            "id": "2.5",
            "criterion": "付款计划是否设置明确的付款节点、触发条件、比例及发票类型要求，且预留不低于10%质保金于免费维保期届满后支付",
            "check_points": [
                "确认每个付款节点是否绑定具体里程碑事件（如‘初验合格后5个工作日内’）",
                "核查是否约定发票类型（增值税专用发票/普通发票）及开票时间（如‘付款前开具’）",
                "检查质保金比例是否≥10%，支付前提是否限定为‘免费维保期满且无质量异议’"
            ]
        },
        {
            "section": "二、合同框架",
            "id": "2.6",
            "criterion": "合同期限是否以明确起止日期或可推算周期界定，并清晰区分‘自然日’与‘工作日’",
            "check_points": [
                "确认起始日是否以‘签字盖章之日’或具体年月日为准，避免‘自本合同生效之日起’等循环定义",
                "检查终止日是否明确（如‘2025年12月31日’）或可精确计算（如‘自2024年1月1日起满24个月’）",
                "核实所有时间表述是否注明‘自然日’或‘工作日’，尤其在验收、响应、付款等关键期限中"
            ]
        },
        {
            "section": "三、其他基本问题",
            "id": "3.1",
            "criterion": "合同文本是否存在错别字、标点误用、标题层级混乱、金额合计错误、大小写不一致、语法不通顺等基础性文字瑕疵",
            "check_points": [
                "全文通读，标记所有错别字（如‘帐户’应为‘账户’）、冗余空格/换行",
                "检查标题编号是否连续（如‘第一条’后不得跳至‘第三条’）、字体字号是否统一",
                "重新加总付款计划各期金额，验证是否等于合同总额；复核大小写金额一致性"
            ]
        },
        {
            "section": "三、其他基本问题",
            "id": "3.2",
            "criterion": "核查正文与附件中相同事项的约定是否完全一致，尤其关注验收标准、付款条件、知识产权归属等核心条款",
            "check_points": [
                "选取3–5处关键条款（如‘验收流程’‘违约金比例’‘源代码交付义务’），比对正文与附件表述是否一字不差",
                "确认附件是否经双方签署页加盖骑缝章，或在正文中明确‘附件为本合同不可分割的组成部分’",
                "检查附件页码是否连续、是否存在缺页或扫描模糊导致内容不可辨识"
            ]
        },
        {
            "section": "三、其他基本问题",
            "id": "3.3",
            "criterion": "排查合同中是否混入招标、谈判、询价等采购流程中的阶段性用语，确保表述符合最终签署文本定位",
            "check_points": [
                "搜索关键词‘招标文件’‘投标函’‘谈判小组’‘询价响应’等，确认均已删除或替换为‘本合同’‘双方’等终局性表述",
                "核查‘甲方’‘乙方’指代是否始终一致，未出现‘采购人’‘供应商’与‘甲方’‘乙方’混用",
                "删除所有流程性说明文字（如‘根据XX采购办法第X条’），除非该条款本身构成合同权利义务"
            ]
        },
        {
            "section": "三、其他基本问题",
            "id": "3.4",
            "criterion": "合同首部签约主体名称、落款签章处主体名称、以及全文各处引用的主体名称须严格一致，不得存在简称、缩写或错字",
            "check_points": [
                "提取合同首部‘甲方（全称）：’字段，全文搜索该全称出现次数及位置",
                "比对签署页‘甲方（盖章）：’后所留空白处填写名称是否与首部完全一致（含括号、顿号、空格）",
                "检查正文中所有‘甲方’‘乙方’指代是否均指向首部定义主体，无‘贵司’‘我方’等口语化或歧义表述"
            ]
        },
        {
            "section": "三、其他基本问题",
            "id": "3.5",
            "criterion": "核查合同中援引的法律法规、部门规章、强制性标准是否现行有效，且名称、文号、条款序号准确无误",
            "check_points": [
                "对每处法律援引（如‘依据《民法典》第五百零九条’）进行有效性验证，确认该条款未被修订或废止",
                "检索国务院、市场监管总局、工信部等官网，确认所引规章（如《网络安全审查办法》）是否仍为有效版本",
                "核对国家标准编号（如‘GB/T 22239-2019’）是否真实存在且现行有效"
            ]
        },
        {
            "section": "三、其他基本问题",
            "id": "3.6",
            "criterion": "合同正文末尾是否规范标注‘以下为合同签署栏’或‘以下无正文’字样，防止事后擅自添加内容",
            "check_points": [
                "确认正文最后一段结束后，紧接一行居中打印‘以下为合同签署栏’或‘以下无正文’",
                "检查该字样与签署栏之间无空白行或多余空格，签署栏是否包含甲方/乙方名称、授权代表签字、盖章、日期等完整要素",
                "核实签署栏是否独立成页，未与正文混排或跨页断裂"
            ]
        }
    ]
}
